import InternalCode from "#codes";
import db from "#db";
import valid, { validChannelId } from "#logic/validData";
import { Router } from "@wxn0brp/falcon-frame";

export const announcementRouter = new Router();

announcementRouter.get("/announcement", async (req, res) => {
	let {
		realm,
		chnl,
		start: startStr,
		end: endStr,
	} = req.query as {
		realm: string;
		chnl: string;
		start: string;
		end: string;
	};
	const start = parseInt(startStr);
	const end = parseInt(endStr);

	if (!valid.id(realm))
		return res.json({
			err: true,
			c: InternalCode.UserError.Express.MissingParameters,
			msg: "realm",
		});
	if (!validChannelId(chnl))
		return res.json({
			err: true,
			c: InternalCode.UserError.Express.MissingParameters,
			msg: "channel",
		});
	if (!valid.num(start, 0))
		return res.json({
			err: true,
			c: InternalCode.UserError.Express.MissingParameters,
			msg: "start",
		});
	if (!valid.num(end, 0))
		return res.json({
			err: true,
			c: InternalCode.UserError.Express.MissingParameters,
			msg: "end",
		});

	const chnlData = await db.realmConf.c("realmConf").findOne({ realm, chid: chnl });
	if (!chnlData)
		return res.json({
			err: true,
			c: InternalCode.UserError.Express.Announcement_ChannelIsNotOpen,
			msg: "channel is not open event",
		});
	if (chnlData.type != "open_announcement")
		return res.json({
			err: true,
			c: InternalCode.UserError.Express.Announcement_ChannelIsNotOpen,
			msg: "channel is not open announcement",
		});

	let data = await db.mess.c(realm).find(
		{ chnl },
		{ reverse: true, limit: end + start },
	);
	data = data.slice(start, end).map((msg) => {
		return {
			fr: msg.fr,
			msg: msg.msg,
		};
	});

	res.json({ err: false, data });
});
