import InternalCode from "#codes";
import db from "#db";
import { Id } from "#id";
import { invite } from "#logic/inviteBot";
import { Router } from "@wxn0brp/falcon-frame";
import { authenticateMiddleware } from "../auth";

export const inviteBotRouter = new Router();

inviteBotRouter.get("/", authenticateMiddleware, async (req, res) => {
	const { id, realm } = req.query as { id: Id; realm: Id };
	const { err, msg } = await invite(req.user, id, realm);

	res.json({ err, msg });
});

inviteBotRouter.get("/meta", authenticateMiddleware, async (req, res) => {
	const { id } = req.query as { id: Id };
	if (!id)
		return res.json({
			err: true,
			c: InternalCode.UserError.Express.MissingParameters,
			msg: "id",
		});

	const botExists = await db.botData.c(id).findOne({ _id: "owner" });
	if (!botExists)
		return res.json({
			err: true,
			c: InternalCode.UserError.Express.BotInvite_NotFound,
			msg: "bot not found",
		});

	const botRes = {
		name: undefined,
		realms: undefined,
	};

	botRes.name = await db.botData
		.c(id)
		.findOne({ _id: "name" })
		.then((b) => b.name);

	const userRealms = await db.userData.c(req.user).find({
		$exists: { realm: true },
	});
	const botRealms = await db.botData
		.c(id)
		.find({ $exists: { realm: true } })
		.then((b) => b.map((r) => r.realm));
	const availableRealms = userRealms
		.filter((s) => !botRealms.includes(s.realm))
		.map((s) => s.realm);
	botRes.realms = availableRealms;

	res.json({ err: false, data: botRes });
});

export default inviteBotRouter;
