import InternalCode from "#codes";
import db from "#db";
import { realm_join } from "#scl/chats";
import { Id } from "#id";
import Db_RealmConf from "#types/db/realmConf";
import { Socket_StandardRes_Error } from "#types/socket/res";
import { Socket_User } from "#types/socket/user";
import { Router } from "@wxn0brp/falcon-frame";
import { authenticateMiddleware } from "../auth";

export const realmJoinRouter = new Router();

realmJoinRouter.get("/meta", authenticateMiddleware, async (req, res) => {
	const { id } = req.query as { id: Id };
	if (!id)
		return res.json({
			err: true,
			c: InternalCode.UserError.Express.MissingParameters,
			msg: "id",
		});

	const userExists = await db.userData.c(req.user).findOne({ realm: id });
	if (userExists) return res.json({ err: false, state: 1 });

	const isBaned = await db.realmData.c(id).findOne({ ban: req.user });
	if (isBaned) return res.json({ err: false, state: 2 });

	const realmRes = {
		name: undefined,
		img: undefined,
	};

	const realmMeta = await db.realmConf.c<Db_RealmConf.meta>(id).findOne({
		_id: "set",
	});
	realmRes.name = realmMeta.name;
	realmRes.img = realmMeta.img || false;

	res.json({ err: false, state: 0, data: realmRes });
});

realmJoinRouter.get("/", authenticateMiddleware, async (req, res) => {
	const { id } = req.query as { id: Id };
	const suser: Socket_User = {
		_id: req.user,
		name: undefined,
		email: undefined,
	};
	const data = await realm_join(suser, id);
	if (data.err) {
		const err = data.err as Socket_StandardRes_Error;
		if (err[0] == "error.valid")
			return res.status(400).json({
				err: true,
				c: InternalCode.UserError.Express.MissingParameters,
				msg: err[2],
			});
		else
			return res.json({
				err: true,
				c: InternalCode.UserError.Express.RealmJoin,
				msg: err.slice(2),
			});
	}

	res.json({ err: false, msg: "ok" });
});
