export async function realm_setup(
	suser: Socket_User,
	id: Id,
): Promise<Socket_StandardRes> {
	const validE = new ValidError("realm.setup");
	if (!valid.id(id)) return validE.valid("id");

	const isUserInRealm = await checkIsUserOnRealm(suser._id, id);
	if (!isUserInRealm)
		return validE.err(InternalCode.UserError.Socket.UserNotOnRealm);

	const realmMeta = await db.realmConf.c<Db_RealmConf.meta>(id).findOne({
		_id: "set",
	});
	if (!realmMeta)
		return validE.err(
			InternalCode.UserError.Socket.RealmSetup_RealmNotFound,
		);

	const name = realmMeta.name;
	const permSys = new permissionSystem(id);

	const buildChannels = [];
	const categories = await db.realmConf.c<Db_RealmConf.category>(id).find({
		$exists: { cid: true },
	});

	const channels = await db.realmConf.c<Db_RealmConf.channel>(id).find({ $exists: { chid: true } });
	const sortedCategories = categories.sort((a, b) => a.i - b.i);

	for (let i = 0; i < sortedCategories.length; i++) {
		const category = sortedCategories[i];
		let chnlsByDb = channels
			.filter((c) => c.category == category.cid)
			.sort((a, b) => a.i - b.i);

		const allChnls = await Promise.all(
			chnlsByDb.map(async (c) => {
				const perms = await getChnlPerm(suser._id, id, c.chid);
				if (!perms) return null;
				if (!perms.view) return null;

				return {
					id: c.chid,
					name: c.name,
					type: c.type,
					perms,
					desc: c.desc,
				};
			}),
		);
		const chnls = allChnls.filter(Boolean);

		if (chnlsByDb.length == 0) continue;
		buildChannels.push({
			id: category.cid,
			name: category.name,
			chnls,
		});
	}

	const userPermissions = await permSys.getUserPermissions(suser._id);

	return { err: false, res: [id, name, buildChannels, userPermissions] };
}

export async function realm_users_sync(
	suser: Socket_User,
	id: Id,
): Promise<Socket_StandardRes> {
	const validE = new ValidError("realm.users.sync");
	if (!valid.id(id)) return validE.valid("id");

	const isUserInRealm = await checkIsUserOnRealm(suser._id, id);
	if (!isUserInRealm)
		return validE.err(InternalCode.UserError.Socket.UserNotOnRealm);

	const permSys = new permissionSystem(id);
	const roles = await permSys.getAllRolesSorted();
	const rolesData = roles.map(({ name, c }) => {
		return { name, c };
	});

	const rolesMap = new Map();
	for (const role of roles) rolesMap.set(role._id, role.name);

	const users = await db.realmUser.c(id).find({});
	const usersData = users.map((u) => {
		const uid = u.u || u.bot;
		let symbolUID = uid;
		if (u.bot) symbolUID = "^" + u.bot;

		return {
			uid: symbolUID,
			roles: u.r.map((r: Id) => rolesMap.get(r)),
		};
	});

	return { err: false, res: [usersData, rolesData] };
}

export async function realm_users_activity_sync(
	suser: Socket_User,
	id: Id,
): Promise<Socket_StandardRes> {
	const validE = new ValidError("realm.users.activity.sync");
	if (!valid.id(id)) return validE.valid("id");

	const isUserInRealm = await checkIsUserOnRealm(suser._id, id);
	if (!isUserInRealm)
		return validE.err(InternalCode.UserError.Socket.UserNotOnRealm);

	const users = await db.realmUser.c(id).find({});
	const usersData = users.map(async (u) => {
		const uid = u.u || u.bot;
		let symbolUID = uid;
		if (u.bot) symbolUID = "^" + u.bot;

		let userOnline = false;
		if (u.u) userOnline = io.room("user-" + uid).size > 0;
		if (u.bot) userOnline = io.room("bot-" + uid).size > 0;
		if (!userOnline) return { uid: symbolUID };

		const st = await db.userData.c<Db_UserData.status>(uid).findOne({
			_id: "status",
		});
		const statusText = st?.text;
		const status = st?.status || "online";

		return {
			uid: symbolUID,
			activity: statusMgmtGetCache(uid),
			status,
			statusText,
		};
	});

	const res = await Promise.all(usersData);

	return { err: false, res: [res] };
}

export async function realm_delete(
	suser: Socket_User,
	id: Id,
	name: string,
): Promise<Socket_StandardRes> {
	const validE = new ValidError("realm.delete");
	if (!valid.id(id)) return validE.valid("id");
	if (!valid.str(name, 0, 30)) return validE.valid("name");

	const realmMeta = await db.realmConf.c<Db_RealmConf.meta>(id).findOne({
		_id: "set",
	});
	if (realmMeta.name != name) return validE.valid("name");

	const permSys = new permissionSystem(id);
	const userPerm = await permSys.canUserPerformAction(
		suser._id,
		Permissions.admin,
	);
	if (!userPerm)
		return validE.err(
			InternalCode.UserError.Socket.RealmEdit_NotAuthorized,
		);

	const users = await db.realmUser.c(id)
		.find({})
		.then((users) => users.map((u) => u.u));
	for (const user of users) await db.userData.c(user).removeOne({ realm: id });

	db.realmConf.removeCollection(id);
	db.realmUser.removeCollection(id);
	db.mess.removeCollection(id);
	db.realmData.removeCollection(id);

	for (const user of users)
		sendToUser(user, "refreshData", "realm.get");

	return { err: false };
}

export async function realm_user_kick(
	suser: Socket_User,
	realmId: Id,
	uid: Id,
	ban: boolean = false,
): Promise<Socket_StandardRes> {
	const validE = new ValidError("realm.user.kick");
	if (!valid.id(realmId)) return validE.valid("realmId");
	if (!valid.id(uid)) return validE.valid("uid");
	if (!valid.bool(ban)) return validE.valid("ban");

	const permSys = new permissionSystem(realmId);
	const userPerm = await permSys.canUserPerformAnyAction(suser._id, [
		Permissions.admin,
		Permissions.banUser,
		Permissions.kickUser,
	]);
	if (!userPerm)
		return validE.err(
			InternalCode.UserError.Socket.RealmEdit_NotAuthorized,
		);

	await db.userData.c(uid).removeOne({ realm: realmId });
	await db.realmUser.c(realmId).removeOne({ uid });

	if (ban) {
		await db.realmUser.c(realmId).add({ ban: uid }, false);
	}

	sendToUser(uid, "refreshData", "realm.get");

	return { err: false };
}

export async function realm_user_unban(
	suser: Socket_User,
	realmId: Id,
	uid: Id,
): Promise<Socket_StandardRes> {
	const validE = new ValidError("realm.user.unban");
	if (!valid.id(realmId)) return validE.valid("realmId");
	if (!valid.id(uid)) return validE.valid("uid");

	const perm = new permissionSystem(realmId);
	const userPerm = await perm.canUserPerformAnyAction(suser._id, [
		Permissions.admin,
		Permissions.banUser,
	]);
	if (!userPerm)
		return validE.err(
			InternalCode.UserError.Socket.RealmEdit_NotAuthorized,
		);

	await db.realmUser.c(realmId).removeOne({ ban: uid });
	return { err: false };
}

