export async function realm_announcement_channel_subscribe(
	suser: Socket_User,
	sourceRealmId: Id,
	sourceChannelId: Id,
	targetRealmId: Id,
	targetChannelId: Id,
): Promise<Socket_StandardRes> {
	const validE = new ValidError("realm.announcement.channel.subscribe");
	if (!valid.id(sourceRealmId)) return validE.valid("sourceRealmId");
	if (!valid.id(sourceChannelId)) return validE.valid("sourceChannelId");
	if (!valid.id(targetRealmId)) return validE.valid("targetRealmId");
	if (!valid.id(targetChannelId)) return validE.valid("targetChannelId");

	const permSys = new permissionSystem(targetRealmId);
	const userPerm = await permSys.canUserPerformAction(
		suser._id,
		Permissions.admin,
	);
	if (!userPerm)
		return validE.err(
			InternalCode.UserError.Socket.RealmEdit_NotAuthorized,
		);

	const data = {
		sr: sourceRealmId,
		sc: sourceChannelId,
		tr: targetRealmId,
		tc: targetChannelId,
	};

	const exists = await db.realmData.c("announcement.channels").findOne(data);
	if (exists)
		return validE.err(
			InternalCode.UserError.Socket
				.RealmAnnouncementSubscribe_AlreadySubscribed,
		);

	await db.realmData.c("announcement.channels").add(data, false);
	clearEventCache(targetRealmId);

	return { err: false };
}

